List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> result = new ArrayList<>();
    long timeInterval = getFetchDataDuration();
    for (long i = start; i <= end; i += timeInterval) {
        if (i + timeInterval > end) {
