}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    long durationToProcess = end - start;
    List<TimeRange> timeRanges = new ArrayList<>();

    if (durationToProcess >= FETCH_DATA_DURATION) {
        int rangeCount = (int) Math.ceil(durationToProcess / FETCH_DATA_DURATION);
        long step = durationToProcess / rangeCount;

        for (int i = 0; i < rangeCount; i++) {
            long endOfRange = start + i * step;
            if (endOfRange > end) {
                endOfRange = end;
            }
            timeRanges.add(new TimeRange(start, endOfRange));
            start = endOfRange;
        }
    } else {
        timeRanges.add(new TimeRange(start, end));
    }

    return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end){
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        TimeRange range = new TimeRange(start, Math.min(start + FETCH_DATA_DURATION, end));
        timeRanges.add(range);
        start += FETCH_DATA_DURATION;
    }
    return timeRanges;
}

