            i++;
        } else if (b >= 0xC0 && b <= 0xDF) {
            // 110xxxxx 10xxxxxx
            int count = (b & 0x1F) + 1;
            if (i + count > index + len) {
                throw new StringIndexOutOfBoundsException("Invalid UTF-8 sequence");
            }
            for (int j = 1; j < count; j++) {
                int c = str.charAt(i + j);
                if (c < 0x80 || c > 0xBF) {
                    throw new StringIndexOutOfBoundsException("Invalid UTF-8 sequence");
                }
                i++;
