private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    if (suffix == null) return str == null;
    if (str == null || str.length() < suffix.length()) return false;
    if (!ignoreCase) return str.endsWith(suffix);
    int len = str.length();
    int suffixLen = suffix.length();
    for (int i = 0, j = len - suffixLen; i < len; i++, j--) {
        if (str.charAt(i) != suffix.charAt(j)) return false;
    }
    return true;
}

