public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }

    int nextPrime = 2;
    while (true) {
        if (isPrime(nextPrime) && nextPrime >= desiredCapacity) {
            return nextPrime;
        }
        nextPrime += 2;
    }
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }
    if (n <= 3) {
        return true;
    }
    if (n % 2 == 0 || n % 3 == 0) {
        return false;
    }

    for (int i = 5; i * i <= n; i += 6) {
        if (n % i == 0 || n % (i + 2) == 0) {
            return false;
        }
    }

    return true;
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 2) {
        return 2;
    }
    int n = desiredCapacity + 4; // Start checking from the next greater prime number
    boolean isPrime = true;
    for (int i = 2; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            isPrime = false;
            break;
        }
    }
    if (isPrime) {
        return n;
    }
    return nextPrime(n - 1); // Try the next smaller number
}

