    GraphPath<V,E> path = new GraphPath<>();

    for (E edge : tour) {
        V source = edge.getSource().getVertex();
        V destination = edge.getDestination().getVertex();

        try {
            path.add(source, destination);
        } catch (GraphBuilderException e) {
            e.printStackTrace();
        }
    }

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<DirectedEdge<E>> tourEdges = new ArrayList<>();
    for (E edge : tour) {
        DirectedEdge<E> directedEdge = graph.getEdge(edge);
        tourEdges.add(directedEdge);
    }
    GraphPath<V,E> graphPath = new GraphPath<>(graph);
    graphPath.setEdges(tourEdges);
    return graphPath;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Initialize the graph path
    GraphPath<V, E> path = new GraphPath<>();

    // Iterate over each edge in the tour set
    for (E edge : tour) {
        // Add edge to the graph path
        path.addEdge(edge.getSource(), edge.getTarget());
    }

    // Return the graph path
    return path;
}

public GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    GraphPath<V, E> path = new GraphPath<>(graph);
    for (E edge : tour) {
        V source = edge.getSource();
        V target = edge.getTarget();
        path.addSourceEdge(source);
        path.addTargetEdge(target);
    }
    return path;
}

