    int length = s.length();
    if (length % 4 != 0) {
        throw new IllegalArgumentException("Base64 string is not proper length");
    }
    byte[] byteArray = new byte[length / 4 * 3];
    for (int i = 0, offset = 0; i + 3 < length; i += 4) {
        int high = (s.charAt(i) - 'A') << 4;
        int low = (s.charAt(i + 1) - 'A') << 2;
        byteArray[offset++] = (byte) (high + low);

        high = (s.charAt(i + 2) - 'A') << 4;
        low = (s.charAt(i + 3) - 'A');
        byteArray[offset++] = (byte) (high + low);
    }
    if (length % 4 == 2) {
        int high = (s.charAt(length - 2) - 'A') << 4;
        int low = (s.charAt(length - 1) - 'A') << 2;
        byteArray[offset++] = (byte) (high + low);
    } else if (length % 4 == 3) {
        int high = (s.charAt(length - 3) - 'A') << 4;
        int low = (s.charAt(length - 2) - 'A') << 2;
        int mid = (s.charAt(length - 1) - 'A') << 4;
        byteArray[offset++] = (byte) (high + low + mid);
    }
    return new String(byteArray);
}

