public class GraphUtils {

    /**
     * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
     * @param graph the graph.
     * @param vertices the vertices to induce the subgraph from.
     * @return true if the induced subgraph is a clique.
     */
    public static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
        if (vertices == null || graph == null) {
            throw new IllegalArgumentException("Vertices and graph cannot be null");
        }

        if (vertices.isEmpty()) {
            return true; // Empty set of vertices means the subgraph induced by the empty set is trivially a clique
        }

        UndirectedGraph<V, E> inducedSubgraph = new UndirectedGraph<>(graph);
        for (V vertex : vertices) {
            inducedSubgraph.removeAllEdges(vertex);
        }

        for (V vertex : inducedSubgraph.getBody().keySet()) {
            Set<E> outEdges = inducedSubgraph.getOutgoingEdges(vertex);
            if (outEdges.size() < vertices.size() - 1) {
                return false; // If there are fewer than vertices-1 outgoing edges, the subgraph is not a clique
            }
        }

        return true;
    }
}

